+// Summarises an epoch's readings for a one-line log entry.
+export function epochSummary(readings) {
+  const values = readings.map((reading) => reading.value).filter(Number.isFinite);
+  if (values.length === 0) return "no readings";
+  const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
+  return `${values.length} readings, mean ${mean.toFixed(3)}`;
+}

